INSERT INTO `chat_message` VALUES (6001,5001,'USER','Tôi b? dau d?u, nên làm gì?','2026-05-25 14:31:51'),(6002,5001,'BOT','B?n nên ngh? ngoi, u?ng nhi?u nu?c và có th? dùng paracetamol. N?u dau nhi?u hãy d?n khám.','2026-05-25 14:31:51'),(6003,5002,'USER','Chi phí khám chuyên khoa tim m?ch bao nhiêu?','2026-05-25 14:31:51'),(6004,5002,'BOT','Phí khám t? 150.000d d?n 650.000d tùy bác si. B?n có th? d?t l?ch qua ?ng d?ng.','2026-05-25 14:31:51'),(10000,10000,'USER','Chào bác si, tôi mu?n h?i v? k?t qu? xét nghi?m','2026-06-11 21:00:22'),(10001,10000,'BOT','Chào b?n, k?t qu? xét nghi?m c?a b?n bình thu?ng. Các ch? s? d?u trong ngu?ng cho phép.','2026-06-11 21:00:22'),(10002,10000,'USER','C?m on bác si, tôi có c?n kiêng gì không?','2026-06-11 21:00:22'),(10003,10000,'BOT','B?n nên duy trì ch? d? an u?ng lành m?nh, t?p th? d?c d?u d?n và tái khám dúng l?ch.','2026-06-11 21:00:22');
