INSERT INTO `service` VALUES (1,'Gói Xét Nghi?m Sinh Hóa Co B?n T?i Nhà','LAB_TEST',15,1015000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-c09a907bb4fb4123913d67fd71b13bd1.jpg',616481.00,'Gói xét nghi?m sinh hóa co b?n giúp dánh giá ch?c nang gan, th?n, du?ng máu và m? máu. K?t qu? nhanh, phù h?p ki?m tra s?c kh?e d?nh k?.',1,1,'2026-06-11 02:21:57.000000'),(2,'Gói xét nghi?m s?c kh?e sinh s?n n? - nâng cao (6 test)','LAB_TEST',15,1338000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV008.jpg',879677.00,'Gói xét nghi?m toàn di?n cho s?c kh?e sinh s?n n?, bao g?m 6 ch? s? quan tr?ng, giúp phát hi?n s?m các b?t thu?ng n?i ti?t và ph? khoa.',1,2,'2026-06-11 02:21:57.000000'),(3,'Gói XN Viêm gan - co b?n (3 test)','LAB_TEST',15,420000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV011.jpg',237373.00,'Xét nghi?m viêm gan co b?n v?i 3 ch? s?: HBsAg, Anti-HCV, men gan. Sàng l?c nguy co viêm gan B, C và dánh giá ch?c nang gan.',1,3,'2026-06-11 02:21:57.000000'),(4,'Gói XN dái tháo du?ng - co b?n (3 test)','LAB_TEST',15,159000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV013.jpg',88006.00,'Xét nghi?m dái tháo du?ng co b?n v?i du?ng máu dói, HbA1c, và dung n?p glucose, giúp phát hi?n s?m ti?u du?ng và ti?n dái tháo du?ng.',1,4,'2026-06-11 02:21:57.000000'),(5,'Gói xét nghi?m máu co b?n - Nam/N?','LAB_TEST',15,2110000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-pkvietuc_GK007.jpg',1206834.00,'Gói xét nghi?m máu t?ng quát cho nam/n?, bao g?m công th?c máu, du?ng máu, m? máu, ch?c nang gan th?n – dánh giá s?c kh?e t?ng th?.',1,5,'2026-06-11 02:21:57.000000'),(6,'Gói XN Viêm gan - nâng cao (6 test)','LAB_TEST',15,1117000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV012.jpg',781128.00,'Gói xét nghi?m viêm gan nâng cao v?i 6 ch? s?: HBsAg, Anti-HBs, Anti-HCV, HBV-DNA, HCV-RNA và men gan. Phát hi?n chi ti?t tình tr?ng nhi?m virus.',1,6,'2026-06-11 02:21:57.000000